package org.sleepwell.app;
import java.time.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public final class SunriseScheduleTest {
    final ZoneId ny=ZoneId.of("America/New_York");final LocalDate date=LocalDate.of(2026,10,23);final SunriseSchedule schedule=new SunriseSchedule(40.72,-74.02,0,true);final String nonce="d679855a-69a3-4cc9-8a1f-e4906a00ea92";
    @Test public void offsetChangesRealDeadlineAndClaimUsesExactComputedInstant(){long base=schedule.on(date,7,0,ny).at;SunriseSchedule early=new SunriseSchedule(40.72,-74.02,-30,true);assertEquals(base-1800000,early.on(date,7,0,ny).at);assertTrue(early.occurs(7,0,Set.of(5),null,base-1800000,ny));assertFalse(early.occurs(7,0,Set.of(5),null,base,ny));}
    @Test public void repeatingWeekdaysAndPastTodayUseNextMatchingSunrise(){long friday=schedule.on(date,7,0,ny).at;assertEquals(friday,schedule.next(7,0,Set.of(5),null,friday-1,ny,null));assertEquals(schedule.on(date.plusWeeks(1),7,0,ny).at,schedule.next(7,0,Set.of(5),null,friday,ny,null));assertEquals(schedule.on(date.plusDays(3),7,0,ny).at,schedule.next(7,0,Set.of(1,2,3,4,5),null,friday,ny,null));}
    @Test public void explicitDateNeverRollsForwardOrDeliversTwice(){long at=schedule.on(date,7,0,ny).at;assertEquals(at,schedule.next(7,0,Set.of(),date,at-1,ny,null));assertEquals(0,schedule.next(7,0,Set.of(),date,at,ny,null));assertTrue(schedule.occurs(7,0,Set.of(),date,at,ny));assertFalse(schedule.occurs(7,0,Set.of(),date,schedule.on(date.plusDays(1),7,0,ny).at,ny));}
    @Test public void absentSunriseUsesAcknowledgedClockWithOrdinaryDstResolution(){SunriseSchedule polar=new SunriseSchedule(90,0,0,true);LocalDate gap=LocalDate.of(2026,3,8),fold=LocalDate.of(2026,11,1);for(LocalDate day:new LocalDate[]{gap,fold}){SunriseSchedule.Result result=polar.on(day,2,30,ny);assertTrue(result.fallback);assertEquals(AlarmDate.at(day,2,30,ny),result.at);assertTrue(polar.occurs(2,30,Set.of(),day,result.at,ny));}assertTrue(polar.on(LocalDate.of(2101,1,1),6,45,ny).fallback);}
    @Test public void offsetCrossingTargetDateUsesClockInsteadOfChangingSelectedWeekday(){SunriseSchedule value=new SunriseSchedule(0,0,-120,true);LocalDate day=LocalDate.of(2026,3,20);ZoneId zone=ZoneId.of("Etc/GMT+6");SunriseSchedule.Result result=value.on(day,7,15,zone);assertTrue(result.fallback);assertTrue(result.reason.contains("crosses"));assertEquals(AlarmDate.at(day,7,15,zone),result.at);}
    @Test public void skippedSolarInstantIsFrozenAndOnlyThatOccurrenceIsExcluded(){long at=schedule.on(date,7,0,ny).at;AlarmSkip skip=new AlarmSkip(nonce,date,7,0,Set.of(5),ny.getId(),at,schedule.key());assertEquals(at,skip.at(ZoneId.of("Asia/Riyadh")));assertTrue(skip.matches(7,0,Set.of(5),schedule,null));assertFalse(skip.matches(7,0,Set.of(5),new SunriseSchedule(40.72,-74.02,15,true),null));assertFalse(skip.matches(7,0,Set.of(5),null,null));assertEquals(schedule.on(date.plusWeeks(1),7,0,ny).at,schedule.next(7,0,Set.of(5),null,at-1,ny,skip));assertEquals(0,schedule.next(7,0,Set.of(5),date,at-1,ny,skip));}
    @Test public void sameCoordinatesInNewPhoneZoneUseItsSelectedLocalDate(){long before=schedule.on(date,7,0,ny).at;ZoneId changed=ZoneId.of("Etc/GMT+12");long after=schedule.on(date,7,0,changed).at;assertEquals(date,Instant.ofEpochMilli(after).atZone(changed).toLocalDate());assertNotEquals(before,after);assertEquals(schedule.key(),new SunriseSchedule(40.72,-74.02,0,true).key());}
    @Test public void configurationRequiresFiniteBoundsAndExplicitFallbackConsent(){assertThrows(IllegalArgumentException.class,()->new SunriseSchedule(0,0,0,false));for(int offset:new int[]{-121,121})assertThrows(IllegalArgumentException.class,()->new SunriseSchedule(0,0,offset,true));assertThrows(IllegalArgumentException.class,()->new SunriseSchedule(Double.NaN,0,0,true));assertEquals(new SunriseSchedule(0,0,0,true).key(),new SunriseSchedule(-0d,-0d,0,true).key());}
    @Test public void skippedWholeCalendarDateDoesNotProduceDuplicateRepeatingFallback(){SunriseSchedule polar=new SunriseSchedule(90,0,0,true);ZoneId apia=ZoneId.of("Pacific/Apia");LocalDate missing=LocalDate.of(2011,12,30);long at=polar.next(7,0,Set.of(),null,missing.minusDays(1).atTime(8,0).atZone(apia).toInstant().toEpochMilli(),apia,null);assertEquals(AlarmDate.at(missing.plusDays(1),7,0,apia),at);assertTrue(polar.occurs(7,0,Set.of(),null,at,apia));}
}
